def list_files_recursive(dir_path, max_depth=3):
    files = []
    for root, dirs, filenames in os.walk(dir_path):
        if max_depth > 0:
            for d in list(dirs):
                dirs.remove(d)
                max_depth -= 1
        for f in filenames:
